"""Prepare the wide-sweep executable without opening hardware or sending pulses."""
import base64,gzip,hashlib,json,os
from pathlib import Path
assert os.uname().machine=='aarch64'
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()=='3e1add36-b917-4289-91dc-699348528782'
p=Path('/home/root/aura-pan-follow-20261020/prepared-wide-visible-01')
p.mkdir(parents=True,exist_ok=True)
assert not p.is_symlink()
raw=gzip.decompress(base64.b64decode(''))
assert hashlib.sha256(raw).hexdigest()=='368705eb0c20947b64ccf4b28e7fb51ab1286905810594f9dbe5d349ccd71e36'
compile(raw,'prepared-wide-execute.py','exec')
target=p/'execute.py'
assert not target.is_symlink()
if target.exists():assert target.read_bytes()==raw
else:
 with target.open('xb') as stream:stream.write(raw)
print(json.dumps({'status':'PREPARED_NO_HARDWARE_ACCESSED','execute_file':str(target),'sha256':'368705eb0c20947b64ccf4b28e7fb51ab1286905810594f9dbe5d349ccd71e36','bench_sha256':'85e66459ccdd8cf3009a6666d879de87c3afe843548936d216996767a9640815','pwm_command_emitted':False}),flush=True)
